-- 4. Questions (Topic 65: SDLC & STLC Models - 13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001001', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'What does "SDLC" stand for?', '["Software Data Life Cycle", "Software Development Life Cycle", "System Design Logical Code", "Software Delivery Life Cycle"]', 'Software Development Life Cycle', 'SDLC is a process followed for a software project, within a software organization.', 'active'),
('60000000-0000-0000-0000-000000001002', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'What does "STLC" stand for?', '["Software Testing Life Cycle", "System Testing Life Cycle", "Standard Test Logic Code", "Software Tool Life Cycle"]', 'Software Testing Life Cycle', 'STLC is a sequence of specific activities conducted during the testing process to ensure software quality goals are met.', 'active'),
('60000000-0000-0000-0000-000000001003', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'Which SDLC model is a linear and sequential approach?', '["Agile", "Waterfall", "Spiral", "V-Model"]', 'Waterfall', 'Waterfall model progresses through phases like a stream.', 'active'),
('60000000-0000-0000-0000-000000001004', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'In Agile, what is a "Sprint"?', '["A long-distance race", "A set period of time during which specific work has to be completed and made ready for review", "A type of bug", "A meeting with the boss"]', 'A set period of time during which specific work has to be completed and made ready for review', 'Sprints are the heartbeat of Agile development.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001005', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'What is the main difference between Requirement Analysis and Test Planning in STLC?', '["Requirement analysis is about what to test, test planning is about how and when", "They are identical", "Requirement analysis is for devs, planning for testers", "Analysis is the last step"]', 'Requirement analysis is about what to test, test planning is about how and when', 'Requirement analysis identifies testable requirements, and planning defines the overall strategy.', 'active'),
('60000000-0000-0000-0000-000000001006', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'What is "Shift Left" testing?', '["Moving all blocks to the left in UI", "Testing as early as possible in the SDLC", "Deleting requirements", "A type of programming shortcut"]', 'Testing as early as possible in the SDLC', 'Shift-left helps identify and fix bugs earlier when they are cheaper to resolve.', 'active'),
('60000000-0000-0000-0000-000000001007', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'What is the "V-Model" in testing?', '["A model shaped like a V", "A model where development and testing phases run in parallel/association", "A type of bug tracking", "A fast development method"]', 'A model where development and testing phases run in parallel/association', 'The V-model emphasizes verification and validation at each level.', 'active'),
('60000000-0000-0000-0000-000000001008', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'What happens during "Test Case Development" in STLC?', '["The software is written", "The actual test cases and automated scripts are created", "The product is launched", "The budget is decided"]', 'The actual test cases and automated scripts are created', 'This phase follows test planning.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001009', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'What is "Regression Testing"?', '["Testing once and never again", "Re-running functional and non-functional tests to ensure that previously developed and tested software still performs after a change", "Testing for old computers", "A type of load test"]', 'Re-running functional and non-functional tests to ensure that previously developed and tested software still performs after a change', 'Regression testing prevents "side effects" from new changes.', 'active'),
('60000000-0000-0000-0000-000000001010', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'Explain "UAT" (User Acceptance Testing).', '["Testing by developers", "The final phase of testing, performed by end users in a real-world scenario", "Testing the UI design", "Testing the database speed"]', 'The final phase of testing, performed by end users in a real-world scenario', 'UAT ensures the product meets the business requirements and is ready for use.', 'active'),
('60000000-0000-0000-0000-000000001011', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'What is "Static Testing"?', '["Testing when the server is down", "A type of software testing which is performed without executing the program", "Testing with a lot of noise", "A type of UI layout"]', 'A type of software testing which is performed without executing the program', 'Static testing includes code reviews, inspections, and walkthroughs.', 'active'),
('60000000-0000-0000-0000-000000001012', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'What is "Test Closure" in STLC?', '["Closing the office", "The final stage where a report is generated showing a summary of everything that happened during testing", "Deleting the code", "Launching the app"]', 'The final stage where a report is generated showing a summary of everything that happened during testing', 'Closure involves cleaning up test environments and documenting lessons learned.', 'active'),
('60000000-0000-0000-0000-000000001013', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'Explain "Verification" vs "Validation".', '["They are the same", "Verification is building the product right; Validation is building the right product", "One is for bugs, one for features", "A type of UI design"]', 'Verification is building the product right; Validation is building the right product', 'Verification checks if the product conforms to specifications; Validation checks if it meets user needs.', 'active');

-- Topic 66: Testing Types & Techniques (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001014', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'What is "Black Box Testing"?', '["A system where the tester has no prior knowledge of the target", "Testing in a dark room", "A database test", "A network tool"]', 'A system where the tester has no prior knowledge of the target', 'Black box testing focuses on inputs and outputs without looking at the internal code.', 'active'),
('60000000-0000-0000-0000-000000001015', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'What is "White Box Testing"?', '["Testing a white computer", "A method where the tester has full knowledge of the target system including source code", "A method where the tester has no knowledge", "A type of UI design"]', 'A method where the tester has full knowledge of the target system including source code', 'White box testing evaluates internal structures or workings of an application.', 'active'),
('60000000-0000-0000-0000-000000001016', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'What is "Unit Testing"?', '["Testing a whole building", "Testing individual components or pieces of code to ensure they work correctly", "Testing the internet", "A type of login"]', 'Testing individual components or pieces of code to ensure they work correctly', 'Unit tests are usually written by developers.', 'active'),
('60000000-0000-0000-0000-000000001017', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'What is an "Integration Test"?', '["Merging two companies", "Testing that two or more software units work together correctly", "Testing the UI color", "A database backup"]', 'Testing that two or more software units work together correctly', 'Integration testing identifies issues in the communication between modules.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001018', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'What is "Boundary Value Analysis"?', '["Testing if a wall is strong", "A black box test design technique in which testing is focused on the boundaries of the input domain", "A network scan", "A code review"]', 'A black box test design technique in which testing is focused on the boundaries of the input domain', 'Errors often occur at the edges of allowed ranges (e.g., 0, 1, 99, 100).', 'active'),
('60000000-0000-0000-0000-000000001019', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'What is "Equivalence Partitioning"?', '["Dividing a cake", "A black box test design technique that divides the input data of a software unit into partitions of equivalent data from which test cases can be derived", "A type of math", "A database index"]', 'A black box test design technique that divides the input data of a software unit into partitions of equivalent data from which test cases can be derived', 'This reduces the total number of test cases needed to a manageable level.', 'active'),
('60000000-0000-0000-0000-000000001020', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'What is "Sanity Testing"?', '["Checking if the tester is okay", "A subset of regression testing to verify that a new code change/bug fix is working as expected", "A type of load test", "A security scan"]', 'A subset of regression testing to verify that a new code change/bug fix is working as expected', 'Sanity testing is usually narrow and deep on a specific feature.', 'active'),
('60000000-0000-0000-0000-000000001021', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'What is "Smoke Testing"?', '["Testing fire alarms", "A preliminary test to reveal simple failures severe enough to reject a prospective software release", "Testing with a lot of noise", "A database backup"]', 'A preliminary test to reveal simple failures severe enough to reject a prospective software release', 'Smoke testing verifies if the build is stable enough for further testing.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001022', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'What is "Exploratory Testing"?', '["Traveling to a new country", "A type of software testing where the tester "explores" the app without predefined test cases", "A type of automated test", "A database query"]', 'A type of software testing where the tester "explores" the app without predefined test cases', 'Exploratory testing relies on the tester''s skill and intuition.', 'active'),
('60000000-0000-0000-0000-000000001023', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'Explain "Ad-hoc Testing".', '["Scheduled testing", "An unplanned, informal testing activity that does not follow any documentation", "A type of UI design", "A network scan"]', 'An unplanned, informal testing activity that does not follow any documentation', 'Ad-hoc testing is performed after the formal testing is completed.', 'active'),
('60000000-0000-0000-0000-000000001024', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'What is "Grey Box Testing"?', '["A mix of black and white box testing where the tester has limited knowledge of the internal workings", "Testing a grey computer", "A type of math", "A database error"]', 'A mix of black and white box testing where the tester has limited knowledge of the internal workings', 'Grey box testing often involves looking at database schemas or system architecture.', 'active'),
('60000000-0000-0000-0000-000000001025', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'What is "Non-Functional Testing"?', '["Testing if the app is pretty", "Testing the aspects of the software that are not related to specific functions or user actions (e.g., performance, security)", "Testing the code layout", "A type of UI design"]', 'Testing the aspects of the software that are not related to specific functions or user actions (e.g., performance, security)', 'Non-functional tests verify the system''s quality attributes.', 'active'),
('60000000-0000-0000-0000-000000001026', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'Explain "Monkey Testing".', '["Testing by monkeys", "A technique where the user provides random inputs to a system to check for crashes or errors", "A type of UX design", "A network routing protocol"]', 'A technique where the user provides random inputs to a system to check for crashes or errors', 'Monkey testing is a type of stress test for resilience.', 'active'),

-- Topic 67: Unit Testing Frameworks (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001027', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'Which of these is a popular Javascript unit testing framework?', '["React", "Jest", "Vue", "Tailwind"]', 'Jest', 'Jest is widely used for testing React and other JS applications.', 'active'),
('60000000-0000-0000-0000-000000001028', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'In unit testing, what is an "Assertion"?', '["A strong guess", "A statement that compares the actual result of a test with the expected result", "A type of variable", "A UI component"]', 'A statement that compares the actual result of a test with the expected result', 'If the assertion fails, the test fails.', 'active'),
('60000000-0000-0000-0000-000000001029', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'What does "TDD" stand for?', '["Test Driven Development", "Total Data Delivery", "Technical Design Document", "Time Dependent Design"]', 'Test Driven Development', 'TDD involves writing tests before writing the actual code.', 'active'),
('60000000-0000-0000-0000-000000001030', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'What is "Mocking" in unit testing?', '["Making fun of someone", "The practice of creating fake versions of dependencies to isolate the unit being tested", "Deleting the code", "A network signal"]', 'The practice of creating fake versions of dependencies to isolate the unit being tested', 'Mocking allows tests to run without relying on real databases or APIs.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001031', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'What is "Test Coverage"?', '["How many people use the test", "A metric used to measure the amount of code that is executed when a test suite runs", "The number of tests", "A security standard"]', 'A metric used to measure the amount of code that is executed when a test suite runs', 'Higher coverage can indicate more thoroughly tested code, but not necessarily better quality.', 'active'),
('60000000-0000-0000-0000-000000001032', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'In Jest, which function is used to group related tests?', '["group()", "describe()", "suite()", "module()"]', 'describe()', 'describe blocks help organize tests into logical units.', 'active'),
('60000000-0000-0000-0000-000000001033', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'What is the "Red-Green-Refactor" cycle?', '["A design choice", "The central process of TDD: write a failing test (Red), make it pass (Green), and improve the code (Refactor)", "Traffic lights", "A type of UI theme"]', 'The central process of TDD: write a failing test (Red), make it pass (Green), and improve the code (Refactor)', 'This cycle ensures code correctness and quality.', 'active'),
('60000000-0000-0000-0000-000000001034', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'What is a "Stub" in unit testing?', '["A broken pencil", "An object that provides predefined answers to calls made during the test", "A type of error", "A network router"]', 'An object that provides predefined answers to calls made during the test', 'Stubs are simpler than mocks and don''t record behavior.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001035', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'What is "Mutation Testing"?', '["Testing biological viruses", "A type of testing where small changes are made to the code to see if the tests catch them", "A design pattern", "Scaling the app automatically"]', 'A type of testing where small changes are made to the code to see if the tests catch them', 'Mutation testing evaluates the effectiveness of the test suite itself.', 'active'),
('60000000-0000-0000-0000-000000001036', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'Explain "Snapshot Testing" in Jest.', '["Taking a photo", "Capturing the rendered output of a component and comparing it to a saved reference file to detect unintended UI changes", "A type of database backup", "A network log"]', 'Capturing the rendered output of a component and comparing it to a saved reference file to detect unintended UI changes', 'Snapshot testing is popular for verifying React component renders.', 'active'),
('60000000-0000-0000-0000-000000001037', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'What is "JUnit"?', '["A type of exercise", "A standard testing framework for the Java programming language", "A type of wallet", "A network fork"]', 'A standard testing framework for the Java programming language', 'JUnit is the ancestor of most modern unit testing frameworks.', 'active'),
('60000000-0000-0000-0000-000000001038', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'What is the role of "babel-jest"?', '["Speaking many languages", "A plugin that allows Jest to work with modern Javascript features using Babel", "A type of database", "A cloud region"]', 'A plugin that allows Jest to work with modern Javascript features using Babel', 'babel-jest handles the transformation of code before testing.', 'active'),
('60000000-0000-0000-0000-000000001039', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'In unit testing, what is "Idempotency"?', '["The ability to delete all data", "Ensuring that performing an operation multiple times has the same effect as performing it once", "Making code runs faster", "Thread safety"]', 'Ensuring that performing an operation multiple times has the same effect as performing it once', 'Idempotency is important for tests that interact with external state or setup/teardown.', 'active'),

-- Topic 68: E2E & UI Automation (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001040', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'What does "E2E" stand for?', '["Easy to Edit", "End to End", "Every Unit Every day", "Expert Technical Engine"]', 'End to End', 'E2E testing verifies the entire software product from start to finish, including its integration with external interfaces.', 'active'),
('60000000-0000-0000-0000-000000001041', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'Which tool is commonly used for UI automation in web browsers?', '["Photoshop", "Selenium", "Spotify", "Excel"]', 'Selenium', 'Selenium is a broad suite of tools for browser automation.', 'active'),
('60000000-0000-0000-0000-000000001042', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'What is "Cypress"?', '["A type of tree", "A modern front-end testing tool for Web applications", "A database engine", "A network router"]', 'A modern front-end testing tool for Web applications', 'Cypress is known for its speed and developer-friendly features.', 'active'),
('60000000-0000-0000-0000-000000001043', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'What is a "Headless Browser"?', '["A browser with no UI", "An invisible browser used for automation, where web pages are not visually rendered", "A broken app", "A type of VR goggles"]', 'An invisible browser used for automation, where web pages are not visually rendered', 'Headless browsers are faster and more efficient for CI/CD environments.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001044', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'What is the "Page Object Model" (POM)?', '["A type of book", "A design pattern that creates an object repository for storage of all web elements of an application", "A UI layout", "A database schema"]', 'A design pattern that creates an object repository for storage of all web elements of an application', 'POM makes test scripts more readable and maintainable.', 'active'),
('60000000-0000-0000-0000-000000001045', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'What is "Flaky Test"?', '["A crunchy snack", "A test that fails or passes intermittently without any change to the code or environment", "A type of bug", "A fast test"]', 'A test that fails or passes intermittently without any change to the code or environment', 'Flaky tests reduce the team''s trust in the automated test suite.', 'active'),
('60000000-0000-0000-0000-000000001046', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'Explain "Asynchronous Waiting" in UI automation.', '["Waiting for a bus", "Waiting for elements to appear or load without blocking the entire execution", "Sleeping the process", "A network timeout"]', 'Waiting for elements to appear or load without blocking the entire execution', 'Implicit or explicit waits are used to handle dynamic web content.', 'active'),
('60000000-0000-0000-0000-000000001047', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'What is "Cross-browser Testing"?', '["Testing one browser", "The practice of running your application across multiple web browsers and versions to ensure consistent behavior", "Using a lot of monitors", "A type of UI design"]', 'The practice of running your application across multiple web browsers and versions to ensure consistent behavior', 'Cross-browser testing accounts for differences in browser engines.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001048', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'What is "Playwright"?', '["A person who writes plays", "A framework for Web-platform testing and automation that allows for cross-browser testing across Chromium, Firefox and WebKit", "A type of stablecoin", "A security standard"]', 'A framework for Web-platform testing and automation that allows for cross-browser testing across Chromium, Firefox and WebKit', 'Playwright is a powerful competitor to Cypress and Selenium.', 'active'),
('60000000-0000-0000-0000-000000001049', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'Explain "Visual Testing".', '["Looking at the screen", "Automating the verification of the visual appearance of a UI, often using pixel comparison or AI", "A type of photo", "A database record"]', 'Automating the verification of the visual appearance of a UI, often using pixel comparison or AI', 'Visual testing catches layout shifts and styling bugs that regular E2E tests might miss.', 'active'),
('60000000-0000-0000-0000-000000001050', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'What is "Data-driven Testing"?', '["Driven by a car", "A testing methodology where inputs and expected outputs are stored in a data source (e.g., CSV) and many iterations can be ran", "A type of fee", "A network signal"]', 'A testing methodology where inputs and expected outputs are stored in a data source (e.g., CSV) and many iterations can be ran', 'Data-driven testing increases code reuse and allows for testing many scenarios easily.', 'active'),
('60000000-0000-0000-0000-000000001051', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'What is "Appium"?', '["A type of fruit", "An open-source automation framework for mobile applications (iOS and Android)", "A database engine", "A network router"]', 'An open-source automation framework for mobile applications (iOS and Android)', 'Appium uses the WebDriver protocol to automate mobile apps.', 'active'),
('60000000-0000-0000-0000-000000001052', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'What is a "CSS Selector" in the context of UI automation?', '["A color picker", "A way to identify specific elements on a web page to interact with them in a script", "A type of font", "A network routing protocol"]', 'A way to identify specific elements on a web page to interact with them in a script', 'CSS Selectors are a primary method for finding elements in browser automation.', 'active');

-- Topic 69: Load & Performance Testing (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001053', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'What is "Load Testing"?', '["Checking the weight of a computer", "Testing the behavior of a system under a specific expected load", "Testing the UI color", "A type of unit test"]', 'Testing the behavior of a system under a specific expected load', 'Load testing identifies bottlenecks under normal and anticipated peak conditions.', 'active'),
('60000000-0000-0000-0000-000000001054', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'What is "Stress Testing"?', '["Testing if the developer is stressed", "Testing the behavior of a system at or beyond its limits of anticipated load", "A type of UI design", "A code review"]', 'Testing the behavior of a system at or beyond its limits of anticipated load', 'Stress testing determines the breaking point of the system.', 'active'),
('60000000-0000-0000-0000-000000001055', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'Which tool is commonly used for performance testing?', '["Photoshop", "JMeter", "Excel", "Spotify"]', 'JMeter', 'Apache JMeter is a popular open-source load testing tool.', 'active'),
('60000000-0000-0000-0000-000000001056', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'What is "Response Time"?', '["The time it takes to write code", "The time elapsed between a request and the completion of the response", "A type of UI padding", "A network signal"]', 'The time elapsed between a request and the completion of the response', 'Low response time is critical for a good user experience.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001057', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'What is "Throughput" in performance testing?', '["The number of bytes in a file", "The number of transactions or requests processed by the system within a given timeframe", "A type of database index", "A network router"]', 'The number of transactions or requests processed by the system within a given timeframe', 'Throughput measures the capacity of the system.', 'active'),
('60000000-0000-0000-0000-000000001058', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'What is "Soak Testing"?', '["Putting the computer in water", "Testing a system with a significant load over an extended period of time to check for resource leaks", "Testing the UI one time", "A fast regression test"]', 'Testing a system with a significant load over an extended period of time to check for resource leaks', 'Soak tests identify issues like memory leaks or database connection exhaustion.', 'active'),
('60000000-0000-0000-0000-000000001059', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'What is "Spike Testing"?', '["Testing with pointed objects", "Testing the system against sudden and extreme increases in load", "A type of security scan", "A code layout check"]', 'Testing the system against sudden and extreme increases in load', 'Spike testing ensures the system can handle bursts of traffic.', 'active'),
('60000000-0000-0000-0000-000000001060', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'What is "Scalability Testing"?', '["Checking the size of a window", "Testing the ability of a system to "scale up" or "scale out" to handle increased load", "A type of UI theme", "A network protocol"]', 'Testing the ability of a system to "scale up" or "scale out" to handle increased load', 'Scalability tests determine if adding resources leads to proportional performance gains.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001061', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'Explain "Bottleneck analysis".', '["Looking at the neck of a bottle", "The process of identifying the specific resource that limit the overall performance of the system", "A type of UI design", "A network routing rule"]', 'The process of identifying the specific resource that limit the overall performance of the system', 'Common bottlenecks include CPU, memory, disk I/O, or database locks.', 'active'),
('60000000-0000-0000-0000-000000001062', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'What are "Baseline" results?', '["The bottom line of a page", "A set of performance metrics that represent the system''s state under normal conditions, used for future comparison", "A type of error", "A marketing goal"]', 'A set of performance metrics that represent the system''s state under normal conditions, used for future comparison', 'Baselines help determine if new changes have negatively impacted performance.', 'active'),
('60000000-0000-0000-0000-000000001063', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'What is "Ramp-up Time" in load testing?', '["Waking up in the morning", "The time during which the load on the system is gradually increased to the target level", "The time to reach the office", "A network signal"]', 'The time during which the load on the system is gradually increased to the target level', 'Ramp-up prevents overwhelming the system immediately and allows for seeing performance trends.', 'active'),
('60000000-0000-0000-0000-000000001064', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'Explain "Profiling" in performance testing.', '["Creating a user profile", "A form of dynamic program analysis that measures memory, time complexity, or frequency of function calls", "A type of UI layout", "A network sniffer"]', 'A form of dynamic program analysis that measures memory, time complexity, or frequency of function calls', 'Profiling helps pinpoint exact code locations causing performance issues.', 'active'),
('60000000-0000-0000-0000-000000001065', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'What is "Latency" vs "Response Time"?', '["They are identical", "Latency is the "wait time" (time to reach the server); Response Time includes processing time plus latency", "One is for CPU, one for RAM", "A type of database index"]', 'Latency is the "wait time" (time to reach the server); Response Time includes processing time plus latency', 'Latency is a component of total response time.', 'active');

-- Topic 70: API Testing & Tools (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001066', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'What is "API Testing"?', '["Testing the computer keyboard", "Testing the programmatic interfaces of an application to ensure they function correctly and securely", "Testing the UI design", "A type of load test"]', 'Testing the programmatic interfaces of an application to ensure they function correctly and securely', 'API testing focuses on business logic and data exchange.', 'active'),
('60000000-0000-0000-0000-000000001067', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'Which tool is extremely popular for testing and documenting APIs?', '["Photoshop", "Postman", "Spotify", "Excel"]', 'Postman', 'Postman is a leading platform for API development and testing.', 'active'),
('60000000-0000-0000-0000-000000001068', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'What is an "Endpoint" in an API?', '["The end of a file", "A specific URL where an API can be accessed by a client application", "A UI button", "A database table"]', 'A specific URL where an API can be accessed by a client application', 'Endpoints usually correspond to specific resources or actions.', 'active'),
('60000000-0000-0000-0000-000000001069', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'What does a "200 OK" HTTP status code mean?', '["The request failed", "The request was successful", "Unauthorized access", "Not found"]', 'The request was successful', '2xx series codes indicate success.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001070', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'What is the "GET" method used for in APIs?', '["Sending data to a server", "Requesting data from a server", "Deleting data", "Updating data"]', 'Requesting data from a server', 'GET requests should be idempotent and only retrieve data.', 'active'),
('60000000-0000-0000-0000-000000001071', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'What is the "POST" method used for?', '["Ordering a package", "Sending data to a server to create a new resource", "Deleting data", "Closing a connection"]', 'Sending data to a server to create a new resource', 'POST is typically used for creating new entries.', 'active'),
('60000000-0000-0000-0000-000000001072', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'What is "JSON" (JavaScript Object Notation)?', '["A type of network", "A lightweight data-interchange format easy for humans to read and write", "A programming language", "A UI framework"]', 'A lightweight data-interchange format easy for humans to read and write', 'JSON is the standard format for most modern APIs.', 'active'),
('60000000-0000-0000-0000-000000001073', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'What is "REST" architecture?', '["Taking a break", "Representational State Transfer - a set of architectural constraints for building web services", "A fast database", "A network router"]', 'Representational State Transfer - a set of architectural constraints for building web services', 'REST is the most popular architectural style for APIs.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001074', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'What is "Swagger" / "OpenAPI"?', '["A type of clothes", "A specification for documenting and designing RESTful APIs", "A type of firewall", "A cloud region"]', 'A specification for documenting and designing RESTful APIs', 'OpenAPI allows both humans and computers to understand the capabilities of a service without access to source code.', 'active'),
('60000000-0000-0000-0000-000000001075', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'What is "GraphQL" and how is it different from REST?', '["A type of image", "A query language for APIs that allows clients to request exactly the data they need and nothing more", "A faster database", "A network protocol"]', 'A query language for APIs that allows clients to request exactly the data they need and nothing more', 'GraphQL can prevent over-fetching and under-fetching of data.', 'active'),
('60000000-0000-0000-0000-000000001076', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'What is "Mock Server" in API development?', '["A funny server", "A server that simulates the behavior of a real API to allow for development and testing before the actual API is ready", "A backup server", "A network router"]', 'A server that simulates the behavior of a real API to allow for development and testing before the actual API is ready', 'Mock servers decouple frontend and backend development teams.', 'active'),
('60000000-0000-0000-0000-000000001077', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'Explain "API Security" best practices (e.g., OAuth, API Keys).', '["Hiding the server", "Using robust authentication, authorization, and encryption mechanisms to protect API endpoints", "Using easy passwords", "No firewalls"]', 'Using robust authentication, authorization, and encryption mechanisms to protect API endpoints', 'API security prevents unauthorized access and data breaches.', 'active'),
('60000000-0000-0000-0000-000000001078', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'What is "Contract Testing" for APIs?', '["Testing a paper contract", "A technique that ensures two services (e.g., a producer and a consumer) have a shared understanding of their interface", "A type of UI test", "A database query"]', 'A technique that ensures two services (e.g., a producer and a consumer) have a shared understanding of their interface', 'Contract testing prevents breaking changes from being deployed.', 'active');

-- Topic 71: Test Planning & Metrics (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001079', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'What is a "Test Plan"?', '["A layout of the office", "A document detailing the objectives, resources, and processes for a specific software testing effort", "A list of developers", "A database backup"]', 'A document detailing the objectives, resources, and processes for a specific software testing effort', 'The test plan is the foundation of a successful testing project.', 'active'),
('60000000-0000-0000-0000-000000001080', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'What is a "Test Case"?', '["A box for tests", "A set of conditions or variables under which a tester will determine whether a system works correctly", "A type of error", "A UI button"]', 'A set of conditions or variables under which a tester will determine whether a system works correctly', 'Test cases should be clear, concise, and repeatable.', 'active'),
('60000000-0000-0000-0000-000000001081', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'What is a "Defect / Bug"?', '["An insect", "A flaw in a software system that causes it to produce an incorrect or unexpected result", "A new feature", "A design choice"]', 'A flaw in a software system that causes it to produce an incorrect or unexpected result', 'Bugs are identified during the testing process.', 'active'),
('60000000-0000-0000-0000-000000001082', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'What is "Severity" vs "Priority" of a bug?', '["They are the same", "Severity is the impact on the system; Priority is the order in which the bug should be fixed", "One is for users, one for servers", "A type of UI design"]', 'Severity is the impact on the system; Priority is the order in which the bug should be fixed', 'A bug can have high severity but low priority (e.g., an obscure crash).', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000001083', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'What is "Test Data Management"?', '["Managing the testers", "The process of identifying, creating, and managing data needed to execute test cases", "Storing logs", "Buying new servers"]', 'The process of identifying, creating, and managing data needed to execute test cases', 'Proper test data ensures that tests are realistic and effective.', 'active'),
('60000000-0000-0000-0000-000000001084', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'What is a "Defect Life Cycle"?', '["The lifespan of an insect", "The sequence of states that a defect goes through from discovery to closure", "A type of database indexing", "A network routing protocol"]', 'The sequence of states that a defect goes through from discovery to closure', 'Typical states include New, Assigned, Fixed, Retest, and Closed.', 'active'),
('60000000-0000-0000-0000-000000001085', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'What is "RTM" (Requirement Traceability Matrix)?', '["A type of movie matrix", "A document that maps and traces user requirements with test cases", "A database of users", "A marketing tool"]', 'A document that maps and traces user requirements with test cases', 'RTM ensures that all requirements are covered by tests.', 'active'),
('60000000-0000-0000-0000-000000001086', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'What is "Exit Criteria" in testing?', '["Leaving the office early", "A set of conditions that must be met to conclude the testing phase", "The end of a code block", "A network timeout"]', 'A set of conditions that must be met to conclude the testing phase', 'Exit criteria ensure that testing is sufficient and quality goals are achieved.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001087', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'What is "Defect Density"?', '["How thick a bug is", "The number of confirmed defects identified in a software component divided by the size of the component", "Total number of users", "The weight of the code"]', 'The number of confirmed defects identified in a software component divided by the size of the component', 'Defect density helps identify project components that might need more attention.', 'active'),
('60000000-0000-0000-0000-000000001088', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'Explain "Risk-based Testing".', '["Testing if the stock market goes down", "Prioritizing the testing of features based on the risk of their failure and the impact of those failures", "A type of insurance", "A network routing protocol"]', 'Prioritizing the testing of features based on the risk of their failure and the impact of those failures', 'Risk-based testing optimizes the use of limited testing resources.', 'active'),
('60000000-0000-0000-0000-000000001089', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'What is "Test Maturity Model integration" (TMMi)?', '["A type of car", "A framework for measuring the maturity of testing processes in an organization", "A type of testing tool", "A cloud region"]', 'A framework for measuring the maturity of testing processes in an organization', 'TMMi helps organizations continuously improve their testing practices.', 'active'),
('60000000-0000-0000-0000-000000001090', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'What is "Mean Time To Detect" (MTTD)?', '["The time to eat a meal", "The average time it takes for a team to identify that an issue exists", "The number of bugs", "The time to buy a server"]', 'The average time it takes for a team to identify that an issue exists', 'Low MTTD is critical for minimizing the impact of incidents.', 'active'),
('60000000-0000-0000-0000-000000001091', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'What is "Mean Time To Repair" (MTTR)?', '["Fixing a car", "The average time it takes to fix a bug or resolve an incident once it has been identified", "The time to write code", "A network signal"]', 'The average time it takes to fix a bug or resolve an incident once it has been identified', 'MTTR is a key metric for measuring the efficiency of an engineering team.', 'active');

-- Topic 72: CI/CD & Continuous Quality (9 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000001092', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'What is "Continuous Integration" (CI)?', '["Integrating once a year", "The practice of automating the integration of code changes from multiple contributors into a single software project", "Buying more servers", "A type of UI design"]', 'The practice of automating the integration of code changes from multiple contributors into a single software project', 'CI ensures that code is always in a working state.', 'active'),
('60000000-0000-0000-0000-000000001093', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'What is "Continuous Testing"?', '["Testing without stopping for food", "The process of executing automated tests as part of the software delivery pipeline", "A long manual test", "Deleting the code"]', 'The process of executing automated tests as part of the software delivery pipeline', 'Continuous testing provides immediate feedback on the quality of code changes.', 'active'),
('60000000-0000-0000-0000-000000001094', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'What is the goal of "Quality Gates" in a pipeline?', '["To lock the office door", "To ensure that a build only proceeds if it meets certain quality criteria (e.g., passing tests, code coverage)", "To speed up the network", "A type of UI theme"]', 'To ensure that a build only proceeds if it meets certain quality criteria (e.g., passing tests, code coverage)', 'Quality gates prevent buggy code from reaching production.', 'active');
-- Intermediate
('60000000-0000-0000-0000-000000001095', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'What is "Static Code Analysis"?', '["Testing code in your head", "Using tools to analyze source code without executing it for potential bugs, security issues, or styling violations", "Executing the program", "A network scan"]', 'Using tools to analyze source code without executing it for potential bugs, security issues, or styling violations', 'Tools like ESLint or SonarQube are used for static analysis.', 'active'),
('60000000-0000-0000-0000-000000001096', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'What is "Infrastructure as Code" (IaC) in relation to testing?', '["Writing code for buildings", "The management and provisioning of infrastructure (including test environments) through machine-readable definition files", "A type of database", "A network protocol"]', 'The management and provisioning of infrastructure (including test environments) through machine-readable definition files', 'IaC allows for automated and repeatable creation of test environments.', 'active'),
('60000000-0000-0000-0000-000000001097', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'What is "Deployment Automation"?', '["A social media bot", "The process of automating the movement of software between various environments (e.g., dev, test, prod)", "Deleting the code", "A network signal"]', 'The process of automating the movement of software between various environments (e.g., dev, test, prod)', 'Deployment automation reduces human error and speed up the release cycle.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000001098', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'Explain "Canary Releases" in continuous delivery.', '["Using birds in a datacenter", "A technique to reduce the risk of introducing a new software version in production by slowly rolling out the change to a small subset of users", "Stopping all servers", "A type of UI design"]', 'A technique to reduce the risk of introducing a new software version in production by slowly rolling out the change to a small subset of users', 'Canary releases allow for monitoring the new version in production with limited impact if an error occurs.', 'active'),
('60000000-0000-0000-0000-000000001099', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'What is "Chaos Engineering"?', '["Being very messy", "The discipline of experimenting on a software system in production in order to build confidence in the system''s capability to withstand turbulent conditions", "Breaking the database on purpose in dev", "A type of security scan"]', 'The discipline of experimenting on a software system in production in order to build confidence in the system''s capability to withstand turbulent conditions', 'Chaos engineering (like Netflix''s Chaos Monkey) helps build resilient systems.', 'active'),
('60000000-0000-0000-0000-000000001100', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'What is "Shift Right" testing?', '["Testing only in production", "The practice of performing testing, monitoring, and experimentation in the post-release production environment", "Deleting all tests", "A type of UI design"]', 'The practice of performing testing, monitoring, and experimentation in the post-release production environment', 'Shift right includes practices like A/B testing and synthetic monitoring.', 'active');
